import{_ as a,c as e,o as t,af as s}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"40、【解】 坎下震上","description":"子夏易傳 - 40、【解】 坎下震上","frontmatter":{"title":"40、【解】 坎下震上","description":"子夏易傳 - 40、【解】 坎下震上"},"headers":[],"relativePath":"classics/zixia/042.md","filePath":"classics/zixia/042.md"}'),i={name:"classics/zixia/042.md"};function r(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_40、【解】-坎下震上" tabindex="-1">40、【解】 坎下震上 <a class="header-anchor" href="#_40、【解】-坎下震上" aria-label="Permalink to “40、【解】 坎下震上”">​</a></h1><p>卦辭：解，利西南，無所往，其來復吉。有攸往夙吉。</p><p>彖曰：解，險以動，動而免乎險。解，解利西南，往得眾也。其來復吉，乃得中也。有攸往夙吉，往有功也。天地解而雷雨作，雷雨作而百果草木皆甲拆。解之時大矣哉。</p><p>子夏：濟險而動，動出於險，解也。道之夷而無適，不達也。君子可策其名也。解利西南，往而得眾，動於外而有功也。其來復吉，復其所亦可以位也。內剛中而得民也。有攸往夙吉，趨時之敏，緩則無功也。天地解而雷雨作，百果草木皆甲拆，自然之應，不疾而速也。君子貴其途而通也。可無夙乎，非知通於物者，不能通於時也。</p><p>象曰：雷雨作，解。君子以赦過宥罪。</p><p>子夏：雷雨作，上震下澤，釋難之時也。久險不通，人不堪也。赦過宥罪，應乎人心而得其解也。</p><p>初六，無咎。</p><p>象曰：剛柔之際，義無咎也。</p><p>子夏：解，緩也。無阻艱也。況以柔守下而承於剛乎。得其序也。其義固無咎矣。</p><p>九二，田獲三狐，得黃矢，貞吉。</p><p>象曰：九二貞吉，得中道也。</p><p>子夏：剛居中也，能濟其險，眾之所附也。初承以奉之五，正而應之，眾來附之，非我之貪也。難以解矣，可以各保其歸也。守中直而保其正，不幹其邪，得中道正之吉也。</p><p>六三，負且乘，致宼至，貞吝。</p><p>象曰：負且乘，亦可醜也。自我致戎，又誰咎也。</p><p>子夏：履於不正，乘於二，而與之負於四，而係之多妄之陰，貪其非有，亦可醜矣。宼自已致，誰之咎乎。以之為正，可惜者也。</p><p>九四，解而拇，朋至斯孚。</p><p>象曰：解而拇，未當位也。</p><p>子夏：剛處於卑而與三相得，如拇附也。未當位者也。非可久也。故解拇而與，初為朋得其正，乃保其孚矣。</p><p>六五，君子維有解，吉，有孚於小人。</p><p>象曰：君子有解，小人退也。</p><p>子夏：解，行險而免其險也。故下多妄動焉，皆上法之怠，從以濟險而失於緩也。五以柔處，中而繫有，終二守其正而已矣，不敢自解也，故得其中吉也。夫人之化上，從其行也。上難則小人不敢妄進也。</p><p>上六，公用射隼於髙墉之上，獲之。無不利。</p><p>象曰：公用射隼，以解悖也。</p><p>子夏：解，釋弛緩也。故多有縱焉。終而獲之，得其時也。三應其誅焉。縱悖之甚，據非其有，雖欲貪戾，其能終乎。而公以法誅，何所不獲。悖解眾安無不利也。</p>',24)])])}const m=a(i,[["render",r]]);export{f as __pageData,m as default};
